files..config/rofi/colors.rasi:
/* Rofi colors matching the local desktop palette. */
* {
    bg:          #05050577;
    border-color: #64727d;
    bg-alt:      #05050500;
    bg-hover:    #171b1fff;
    bg-selected: #26a65b00;
    fg:          #ffffffff;
    fg-muted:    #8f9aa3ff;
    fg-dark:     #050505;
    fg-selected: rgb(218, 201, 201);
    accent:      #26a65bff;
    accent-soft: #26a65b33;
    urgent:      #eb4d4bff;
}

files..config/hypr/swaync-style.css:
@define-color bg #050505;
@define-color panel #101214;
@define-color panel-alt #171b1f;
@define-color border rgba(100, 114, 125, 0.55);
@define-color text #ffffff;
@define-color muted #8f9aa3;
@define-color accent #26A65B;
@define-color danger #eb4d4b;

* {
    font-family: "JetBrainsMono Nerd Font Propo", sans-serif;
    font-size: 14px;
}

.control-center {
    background: alpha(@bg, 0.94);
    border: 1px solid @border;
    border-radius: 8px;
    padding: 10px;
    box-shadow: 0 18px 48px rgba(0, 0, 0, 0.45);
}

.notification-row {
    outline: none;
}

.notification {
    background: @panel;
    border: 1px solid @border;
    border-radius: 8px;
    margin: 6px;
    padding: 10px;
}

.notification:hover {
    background: @panel-alt;
    border-color: @accent;
}

.notification.critical {
    border-color: @danger;
}

.summary {
    color: @text;
    font-weight: 700;
}

.body,
.time {
    color: @muted;
}

.close-button {
    background: @panel-alt;
    color: @text;
    border: 1px solid @border;
    border-radius: 6px;
    min-width: 22px;
    min-height: 22px;
}

.close-button:hover {
    background: @danger;
    color: @text;
}

.widget-title {
    color: @text;
    margin: 6px;
    padding: 8px;
}

.widget-title button {
    background: @panel-alt;
    color: @text;
    border: 1px solid @border;
    border-radius: 6px;
    padding: 5px 10px;
}

.widget-title button:hover {
    border-color: @accent;
}

.widget-dnd {
    background: @panel;
    border: 1px solid @border;
    border-radius: 8px;
    color: @text;
    margin: 6px;
    padding: 8px;
}

.widget-dnd switch {
    background: @panel-alt;
    border: 1px solid @border;
    border-radius: 999px;
}

.widget-dnd switch:checked {
    background: @accent;
}

.widget-mpris {
    background: @panel;
    border: 1px solid @border;
    border-radius: 8px;
    color: @text;
    margin: 6px;
    padding: 10px;
}

.widget-mpris-title {
    color: @text;
    font-weight: 700;
}

.widget-mpris-subtitle {
    color: @muted;
}
